// ---- EXP-09 (Equal Earth HOI4 map, P00c) begin: off-globe mask helpers. Colour/opacity only, no geometry change. ----
		// Canvas = ee_project.py Canvas(5120, 2304, lon0=10.9, lat 60S..90N); world x = column, world z = rows counted from the bottom.
		float EE_EqEarthY( float vT )
		{
			float vT2 = vT * vT;
			float vT6 = vT2 * vT2 * vT2;
			return vT * ( 1.340264 - 0.081106 * vT2 + vT6 * ( 0.000893 + 0.003796 * vT2 ) );
		}
		float EE_EqEarthDY( float vT )
		{
			float vT2 = vT * vT;
			float vT6 = vT2 * vT2 * vT2;
			return 1.340264 - 0.243318 * vT2 + vT6 * ( 0.006251 + 0.034164 * vT2 );
		}
		// Map pixels outside the Equal Earth outline (<= 0 on the globe): horizontal for the curved sides,
		// vertical for the 90N pole line and the 60S cut. Exact sign, approximate magnitude (used for a soft band only).
		float EE_OffGlobeDistance( float2 vWorldXZ )
		{
			float vScale = 945.82563;     // px per radian = 5120 / ( 2 * 2.7066300 )
			float vZEquator = 1043.67368; // world z of the equator
			float vYTop = 1.31736276;     // Equal Earth y at 90N
			float vYBot = -1.08830084;    // Equal Earth y at 60S
			float vY = ( vWorldXZ.y - vZEquator ) / vScale;
			float vOutY = max( vY - vYTop, vYBot - vY ) * vScale;
			float vYc = clamp( vY, vYBot, vYTop );
			float vT = vYc / 1.340264;
			vT -= ( EE_EqEarthY( vT ) - vYc ) / EE_EqEarthDY( vT );
			vT -= ( EE_EqEarthY( vT ) - vYc ) / EE_EqEarthDY( vT );
			vT -= ( EE_EqEarthY( vT ) - vYc ) / EE_EqEarthDY( vT );
			float vHalfWidth = vScale * 3.14159265 * cos( vT ) / ( 0.86602540 * EE_EqEarthDY( vT ) );
			float vCol = frac( vWorldXZ.x / MAP_SIZE_X ) * MAP_SIZE_X;
			float vOutX = abs( vCol - 0.5 * MAP_SIZE_X ) - vHalfWidth;
			return max( vOutX, vOutY );
		}
		// 0 on the globe, ramps to 1 over vBandPx outside it. Always 0 on any other map size, so vanilla-sized maps are untouched.
		float EE_OffGlobeWeight( float2 vWorldXZ, float vBandPx )
		{
			float vCanvas = step( abs( MAP_SIZE_X - 5120.0 ), 0.5 ) * step( abs( MAP_SIZE_Y - 2304.0 ), 0.5 );
			return saturate( EE_OffGlobeDistance( vWorldXZ ) / vBandPx ) * vCanvas;
		}
		// ---- EXP-09 helpers end ----
